//! Function extents: which original routine owns a code address.
//!
//! The tables are generated by `tools/jp/fallback_extents.py` from the JP
//! analysis map (`~/ac3-jp/analysis/jp_pal_map.tsv` for JP, `pal_side.tsv`
//! for PAL) and the program images. Each version has one table for the
//! resident program and one per overlay module; every overlay loads at the
//! same base, so the module the game has loaded (`common::loaded_module`)
//! selects the table for an address at or above it.
pub mod jp;
pub mod pal;

/// How the JP analysis matched the routine with the other version.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Class {
    /// Identical instructions (addresses masked).
    Exact,
    /// Similarity of at least 0.8.
    Near,
    /// Similarity 0.5..0.8.
    Changed,
    /// No counterpart (JP side).
    New,
    /// No counterpart (PAL side).
    PalOnly,
}
impl Class {
    pub fn name(self) -> &'static str {
        match self {
            Self::Exact => "exact",
            Self::Near => "near",
            Self::Changed => "changed",
            Self::New => "new",
            Self::PalOnly => "pal-only",
        }
    }
}

/// [`Extent::flags`] bits.
pub mod flags {
    /// In the SDK range (PsyQ libraries), not game code.
    pub const SDK: u16 = 1 << 0;
    /// Uses COP0 (status, cause, EPC).
    pub const COP0: u16 = 1 << 1;
    /// Uses `syscall`.
    pub const SYSCALL: u16 = 1 << 2;
    /// Jumps to a BIOS vector (A0h/B0h/C0h).
    pub const BIOS: u16 = 1 << 3;
    /// Touches I/O ports, expansion region 1 or BIOS ROM.
    pub const IO: u16 = 1 << 4;
    /// Touches kernel RAM (0x80000000..0x8000FFFF).
    pub const KERNEL: u16 = 1 << 5;
    /// A libgcc 64-bit helper: its callers read `v1` too.
    pub const WIDE: u16 = 1 << 6;
    /// An SDK routine that is not on the reviewed list of pure CPU library
    /// code (the rest of the SDK drives devices or waits for interrupts).
    pub const UNLISTED: u16 = 1 << 7;
    /// A device routine that leaves its caller's `v0` alone
    /// (ExitCriticalSection): an interpreted caller keeps its own.
    pub const KEEP_V0: u16 = 1 << 8;
    /// A host-coupled translation: its Rust talks to the host at another
    /// level than the original's instructions (see the generator), so
    /// `--interpret` never forces it.
    pub const HOST: u16 = 1 << 9;
    /// A host-call stub: a BIOS or libcard routine the port answers with one
    /// host call (`bios.rs`). Its host-call ID is canonical: the PAL
    /// address of the routine (a JP routine maps through its counterpart;
    /// a JP-only stub keeps its own address). See [`Extent::host_id`].
    pub const STUB: u16 = 1 << 10;
    /// Any reason that puts a routine below the device boundary.
    pub const DEVICE: u16 = COP0 | SYSCALL | BIOS | IO | KERNEL | UNLISTED;

    /// The names of the device reasons in `flags`.
    pub fn reasons(flags: u16) -> Vec<&'static str> {
        [
            (COP0, "cop0"),
            (SYSCALL, "syscall"),
            (BIOS, "bios"),
            (IO, "io"),
            (KERNEL, "kernel"),
            (UNLISTED, "sdk-unlisted"),
        ]
        .into_iter()
        .filter(|(bit, _)| flags & bit != 0)
        .map(|(_, name)| name)
        .collect()
    }
}

/// One original routine: `start..start + size`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Extent {
    pub start: u32,
    pub size: u32,
    pub flags: u16,
    pub class: Class,
    /// The other version's address of the same routine, or 0.
    pub counterpart: u32,
    /// Rust modules that claim the PAL counterpart ("" when none).
    pub owner: &'static str,
    pub name: &'static str,
}

impl Extent {
    pub const fn new(
        start: u32,
        size: u32,
        flags: u16,
        class: Class,
        counterpart: u32,
        owner: &'static str,
        name: &'static str,
    ) -> Self {
        Self {
            start,
            size,
            flags,
            class,
            counterpart,
            owner,
            name,
        }
    }
    pub const fn end(&self) -> u32 {
        self.start.wrapping_add(self.size)
    }
    /// Whether the fallback may interpret it (above the device boundary).
    pub const fn interpretable(&self) -> bool {
        self.flags & flags::DEVICE == 0
    }
    /// The canonical host-call ID of a [`flags::STUB`] routine of `version`:
    /// the PAL SDK address (a JP stub's counterpart, never the JP address,
    /// since JP and PAL stub addresses collide), or a JP-only stub's own
    /// address. `None` for anything else.
    pub const fn host_id(&self, version: Version) -> Option<u32> {
        if self.flags & flags::STUB == 0 {
            return None;
        }
        Some(match version {
            Version::Jp if self.counterpart != 0 => self.counterpart,
            _ => self.start,
        })
    }
    /// Whether `--interpret` may force it (interpretable, not host-coupled).
    pub const fn forceable(&self) -> bool {
        self.interpretable() && self.flags & flags::HOST == 0
    }
    pub const fn contains(&self, address: u32) -> bool {
        address.wrapping_sub(self.start) < self.size
    }
}

/// The game version whose tables the fallback uses.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Version {
    /// SCES-02066 (the reference port; tables for validation).
    Pal,
    /// SLPS-02020/02021 Rev 1.
    Jp,
}

/// A version's tables.
#[derive(Clone, Copy, Debug)]
pub struct Tables {
    pub version: Version,
    /// Resident `$gp`, the value interpreted code starts with.
    pub gp: u32,
    pub overlay_base: u32,
    /// The VBlank counter libetc increments (the host writes it per VBlank).
    pub vblank_counter: u32,
    pub resident: &'static [Extent],
    pub overlays: &'static [&'static [Extent]],
}

impl Tables {
    pub fn of(version: Version) -> Self {
        match version {
            Version::Pal => Self {
                version,
                gp: pal::GP,
                overlay_base: pal::OVERLAY_BASE,
                vblank_counter: pal::VBLANK_COUNTER,
                resident: pal::RESIDENT,
                overlays: &pal::OVERLAYS,
            },
            Version::Jp => Self {
                version,
                gp: jp::GP,
                overlay_base: jp::OVERLAY_BASE,
                vblank_counter: jp::VBLANK_COUNTER,
                resident: jp::RESIDENT,
                overlays: &jp::OVERLAYS,
            },
        }
    }
    /// The table for `address` with overlay `module` loaded, and its index
    /// (0 resident, n overlay module n).
    pub fn table(
        &self,
        address: u32,
        module: impl FnOnce() -> u32,
    ) -> Option<(usize, &'static [Extent])> {
        if address < self.overlay_base {
            return Some((0, self.resident));
        }
        let module = module() as usize;
        let table = self.overlays.get(module.checked_sub(1)?)?;
        Some((module, table))
    }
    /// The routine of `table` whose extent contains `address`, by index.
    pub fn find(table: &[Extent], address: u32) -> Option<usize> {
        let index = table
            .partition_point(|e| e.start <= address)
            .checked_sub(1)?;
        table[index].contains(address).then_some(index)
    }
}
